Lemma lowerc_code_or : forall c, 0 <= c < 256 ->
  Z.lor c (Z.shiftl (Z.b2z ((c + -65) mod 18446744073709551616 <? 26)) 5 mod 18446744073709551616) = lowerc c.
Proof.
  intros c Hc. unfold lowerc.
  assert (M : forall bb : bool, Z.shiftl (Z.b2z bb) 5 mod 18446744073709551616 = Z.shiftl (Z.b2z bb) 5) by (intros [|]; reflexivity).
  rewrite M. clear M.
  destruct (Z.lt_ge_cases c 65) as [LT|GE].
  - replace ((c + -65) mod 18446744073709551616) with (18446744073709551616 + c - 65) by (Z.div_mod_to_equations; lia).
    replace (_ <? 26) with false by (symmetry; apply Z.ltb_ge; lia).
    replace (65 <=? c) with false by (symmetry; apply Z.leb_gt; lia).
    change (Z.shiftl (Z.b2z false) 5) with 0. cbn [andb]. apply Z.lor_0_r.
  - rewrite Z.mod_small by lia. replace (65 <=? c) with true by (symmetry; apply Z.leb_le; lia).
    destruct (Z.le_gt_cases c 90) as [LE|GT].
    + replace (_ <? 26) with true by (symmetry; apply Z.ltb_lt; lia).
      replace (c <=? 90) with true by (symmetry; apply Z.leb_le; lia).
      change (Z.shiftl (Z.b2z true) 5) with 32. cbn [andb].
      (* [comment removed for export] *)
      assert (E : forallb (fun c => Z.lor c 32 =? c + 32) (map Z.of_nat (seq 65 26)) = true) by (vm_compute; reflexivity).
      rewrite forallb_forall in E. specialize (E c). apply Z.eqb_eq. apply E.
      apply in_map_iff. exists (Z.to_nat c). split; [lia|]. apply in_seq. lia.
    + replace (_ <? 26) with false by (symmetry; apply Z.ltb_ge; lia).
      replace (c <=? 90) with false by (symmetry; apply Z.leb_gt; lia).
      change (Z.shiftl (Z.b2z false) 5) with 0. cbn [andb]. apply Z.lor_0_r.
Qed.

