(* [comment removed for export] *)
Lemma ex_fast : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 s0 s1 a0 a1 a4 s2 s3 s4 s5 s6 s7 s8 s9 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (TP VP : Z) (tbs vbs : list byte) (TPj VPj J2 : Z),
  (length tbs - j = k)%nat -> (j <= length tbs)%nat -> length vbs = length tbs ->
  bytes_at asegs m1 TP tbs -> bytes_at asegs m1 VP vbs -> TP + Z.of_nat (length tbs) < 2^64 -> VP + Z.of_nat (length vbs) < 2^64 ->
  accessible m1 TP (Z.of_nat (length tbs)) -> accessible m1 VP (Z.of_nat (length vbs)) ->
  mem_inv asegs m1 ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = true ->
     ex_cont Q 0xbc6e4 rax spx gp tp s0 s1 a4 s2 s3 s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 t4 t5 t6 F fc m1) ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = false ->
     ex_cont Q 0xbc6d8 rax spx gp tp s0 s1 a4 s2 s3 s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 t4 t5 t6 F fc m1) ->
  (* [comment removed for export] *)
  TPj = TP + Z.of_nat j -> VPj = VP + Z.of_nat j -> J2 = Z.of_nat j ->
  evt asegs Q (MS (mkR rax spx gp tp t0 t1 (wz TPj) s0 s1 a0 a1 (wz J2) (wz VPj)
                       a4 (wz (Z.of_nat (length tbs))) (wz VP) (wz TP) s2 s3 s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 t3 t4 t5 t6)
