    WS : bytes_at _ mx ?SP ?sbs, WT : bytes_at _ mx ?TP ?tbs, ST : stk _ mx ?lo ?spa,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, SD : ex_side _ ?LF mx ?lo ?shi ?ff ?fp ?TL ?T ?SP ?TP _ _ |- _ =>
      let CTX := fresh "CTX" in
