                      h0 h1 h2 h3 fj sh16 ebc itc)
        by (unfold ex_ctx, TokItCells, wz, ex_W, AFS_FLAGS;
            split; [exact L | split; [exact EB | split; [exact EA | split; [exact GAP | split; [exact SAV | split; [exact FH |
            split; [exact IT | split; [exact FT | split; [exact SHU | split; [exact FL | split; [exact TLC | split; [exact TC |
            split; [exact WS | split; [exact WT | split; [exact ST | split; [exact MU | split; [exact WM | split; [exact MI | exact SD]]]]]]]]]]]]]]]]]])
  end end.

